<?php include '_header.php';$prod=$conn->query('SELECT COUNT(*) c FROM products')->fetch_assoc()['c'];$users=$conn->query("SELECT COUNT(*) c FROM users WHERE role='user'")->fetch_assoc()['c'];$orders=$conn->query('SELECT COUNT(*) c FROM orders')->fetch_assoc()['c'];$rev=$conn->query("SELECT COALESCE(SUM(grand_total),0) s FROM orders WHERE status<>'Dibatalkan'")->fetch_assoc()['s'];?><h1>Dashboard Admin</h1><p class="muted">Ringkasan aktivitas toko.</p><div class="stats"><div class="stat">Produk<strong><?=$prod?></strong></div><div class="stat">Pelanggan<strong><?=$users?></strong></div><div class="stat">Pesanan<strong><?=$orders?></strong></div><div class="stat">Omzet<strong style="font-size:18px"><?=rupiah($rev)?></strong></div></div><div class="panel"><h3>Pesanan Terbaru</h3><div class="table-wrap"><table class="table"><tr><th>ID</th><th>Pelanggan</th><th>Total</th><th>Status</th></tr><?php $r=$conn->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 8');while($x=$r->fetch_assoc()):?><tr><td>#<?=$x['id']?></td><td><?=htmlspecialchars($x['name'])?></td><td><?=rupiah($x['grand_total'])?></td><td><?=$x['status']?></td></tr><?php endwhile;?></table></div></div><?php include '_footer.php';?>
